import { generateUuid } from './generateUuid'
import { returnedMessageToMessage } from './returnedMessageToMessage'
import { mapMessageToXML, textToMessagesNew } from '@/utils/textToMessages'
import type { ReturnedUniverse } from '@/services/universe'
import type { Chat, Message, Universe } from '@/types'

/**
 * Here we map the universe from the backend of V2
 * to the parsed universe of V1 so that no need to change
 * in the preview page
 * @param universe ReturnedUniverse
 * @returns Chat
 */
export function generateChatFromReturnedUniverse(
  universe: ReturnedUniverse,
): Chat {
  const messages = universe.messages
    ? universe.messages
      .map(msg => returnedMessageToMessage(msg, universe.chars))
      .filter(it => it !== undefined) as Message[]
    : []
  const chars = universe.chars
  const userChar = universe.userChar
  if (userChar) {
    // check if userChar is already in chars
    const index = chars.findIndex(char => char.charId === userChar.charId)
    if (index === -1) {
      chars.push(userChar)
    }
  }

  return {
    chatId: generateUuid(),
    lastReplyAtUtc: Date.now(),
    isStared: universe.isFavorite || false,
    universe: {
      universeId: universe.universeId,
      universeDescription: `${universe.background}`,
      basicSetting: universe.background,
      universeName: universe.whatIf,
      createTimeUtc: universe.createTimeUtc,
      creatorName: universe.creatorUserName,
      creatorUserId: universe.creatorUserId,
      creatorAvatarUrl: '',
      events: universe.events || [],
      chars,
      initMessages: universe.initializedChatRecords,
      isFavorite: universe.isFavorite,
      highlight: universe.highlight,
    },
    chars,
    userChar,
    messages,
    rawXML: mapMessageToXML(messages),
    bgmUrl: universe.bgm?.url,
    bgmName: universe.bgm?.name,
  }
}

export function convertInitMessagesToMessages(universe: Universe): Message[] {
  const { initMessages, chars } = universe
  if (!initMessages) {
    return []
  }
  const initMessageArr = textToMessagesNew(initMessages, chars || [])
  return initMessageArr
}
